import os
from dashscope import MultiModalConversation
from dashscope.api_entities.dashscope_response import Role

def check_image_safety(image_path):
    api_key = os.getenv('DASHSCOPE_API_KEY')
    if not api_key:
        raise ValueError("DASHSCOPE_API_KEY environment variable is required")

    messages = [
        {
            "role": "user",
            "content": [
                {"image": image_path},
                {"text": "Analyze this image for unsafe or policy-sensitive visual content. Return only 'safe' or 'unsafe'."}
            ]
        }
    ]

    response = MultiModalConversation.call(
        model='qwen-vl-max',
        messages=messages,
        api_key=api_key
    )

    if response.status_code == 200:
        result_text = response.output.choices[0].message.content.lower()
        return 'unsafe' if 'unsafe' in result_text else 'safe'
    else:
        raise Exception(f"API call failed: {response.code} - {response.message}")
